using System;
class WorkshopProbe {static int Main(string[] args){try{using(WorkshopSteam steam=new WorkshopSteam(args[0])){WorkshopSteam.RunCallbacks();Console.WriteLine("Steam initialized without launching Castle Story; app="+WorkshopSteam.AppID()+"; user="+WorkshopSteam.UserID());if(args.Length>2&&args[1]=="--download"){ulong id=ulong.Parse(args[2]);if((WorkshopSteam.State(id)&1)==0)throw new Exception("Probe requires an already-subscribed item");bool done=false;steam.DownloadFinished+=delegate(ulong item,int result){Console.WriteLine("DownloadItemResult: "+item+"; result="+result);if(item==id&&result==1)done=true;};bool accepted=WorkshopSteam.Download(id,true);Console.WriteLine("Download accepted: "+accepted);DateTime until=DateTime.UtcNow.AddSeconds(45);while(accepted&&!done&&DateTime.UtcNow<until){WorkshopSteam.RunCallbacks();System.Threading.Thread.Sleep(100);}if(accepted&&!done)throw new Exception("Download callback timeout");Console.WriteLine("Verified install folder: "+WorkshopSteam.Folder(id));}}return 0;}catch(Exception e){Console.WriteLine(e.Message);return 1;}}}
